(function(){
const $=id=>document.getElementById(id),S=LineSim;
let config=[{id:'N1',type:'belt',seconds:1.2,a:'RUN',b:'NEXT_CLEAR',join:'AND'},{id:'N2',type:'sensor',seconds:.5,a:'RUN',b:'NEXT_CLEAR',join:'AND'},{id:'N3',type:'stop',seconds:2,a:'RUN',b:'NEXT_CLEAR',join:'AND'},{id:'N4',type:'lift',seconds:1,a:'RUN',b:'NEXT_CLEAR',join:'AND'},{id:'N5',type:'belt',seconds:1.2,a:'RUN',b:'NEXT_CLEAR',join:'AND'}];let s=S.fresh(),clock=null,storage=true,selection='N1',layout='straight';
try{const v=JSON.parse(localStorage.getItem('plcquest.sandbox.v1'));if(v)config=S.validate(v);}catch{storage=false;}
try{const chosen=localStorage.getItem('plcquest.sandbox.layout.v1');if(['straight','square','oval'].includes(chosen))layout=chosen;}catch{}
s.loop=layout!=='straight';s.autoFeed=!s.loop;S.sync(config,s);if(s.loop)S.feed(config,s);
const view=document.createElement('section');view.id='sandboxView';view.hidden=true;view.innerHTML=`<div class="sandboxintro"><div><span class="eyebrow">BUILD • RUN • TROUBLESHOOT</span><h1>Your conveyor line</h1></div><button id="sbReset" class="quiet">Reset simulation</button></div><p class="sbintro">Add stations in flow order. Tap a station to edit its logic, timing, or fault state.</p><div class="sblayoutbar"><label for="sbLayout">Conveyor layout</label><select id="sbLayout"><option value="straight">Straight line</option><option value="square">Square loop</option><option value="oval">Oval loop</option></select><span id="sbLayoutNote"></span></div><div class="sbtoolbar"><label>Add component <select id="sbType">${S.types.map(t=>`<option value="${t}">${S.titles[t]}</option>`).join('')}</select></label><button id="sbAdd" class="primary">Add station</button><button id="sbFeed" class="quiet">Feed one box</button><label class="checkbox"><input type="checkbox" id="sbAuto" ${s.autoFeed?'checked':''}> Auto feed</label></div><div class="sbtransport"><button id="sbRun" class="copper">Run line</button><button id="sbStep" class="quiet">Step 0.1 second</button><button id="sbCommand" class="quiet" aria-pressed="false">Run input: OFF</button><button id="sbReady" class="quiet" aria-pressed="true">Ready: ON</button></div><p class="sbhint">Run line starts the scans and turns the Run input on. Step advances scans without changing inputs. Each station follows its own logic.</p><div class="sbstats" id="sbStats"></div><div class="linecanvas"><svg id="sbDiagram" role="img" aria-label="Live conveyor system diagram"></svg></div><div id="sbStatus" role="status" aria-live="polite"></div><div class="sbstationtabs" id="sbStations"></div><section class="panel sbeditor" id="sbEditor"></section><details class="sbguide"><summary>How the sandbox works</summary><p>Choose Straight line for an exit, or Square loop / Oval loop to return parts to the first station. A loop starts with one numbered box and counts every completed circuit. Auto feed is off by default in loops. At least one station stays empty to allow parts to circulate. Changing layout resets the simulation but preserves your station configuration.</p><p>Each station has one part position. A full downstream station holds the upstream part, so parts cannot overlap. Photoeyes turn on when a part arrives and turn off when it leaves. Arrival counts increase once per part.</p><p>The two contacts control the station output. AND requires both. OR allows either. Use an inverted contact for a condition that must be off. RUN and READY are shared inputs. LOCAL is the selected station’s manual switch. S_N1, S_N2 and so on are station occupancy sensors.</p><p>A stop gate holds for its preset before releasing. A lift takes 0.8 seconds to rise, holds at its upper limit for its preset, then takes 0.8 seconds to lower before transferring. A reject station sends parts to the reject bin when its Reject switch is on. These component cycles are built in; you program their enable conditions here.</p><p>Reset simulation clears parts and counts, but keeps your line design. Edits pause and reset the simulation. The design saves in this browser. This is a discrete training model, not a physical machine controller or a wiring/safety simulator.</p></details><details class="sbguide"><summary>Learning path beyond these 30 lessons</summary><p>Next topics to master: full sequence state machines, separate actuator commands and limit feedback, one-shot instructions, data types and arrays, analog scaling, HMI alarms, communications, electrical drawings, commissioning, and controlled troubleshooting on training hardware.</p><p>Game completion records practice, not a professional credential. <a href="https://www.rockwellautomation.com/en-us/support/workforce-development-training/certificate-programs.html" target="_blank" rel="noreferrer">Rockwell Automation certificate programs</a> have their own course and assessment requirements.</p></details>`;
 document.querySelector('dialog').before(view);$('sbLayout').value=layout;
function save(){try{localStorage.setItem('plcquest.sandbox.v1',JSON.stringify(config));localStorage.setItem('plcquest.sandbox.layout.v1',layout);storage=true;}catch{storage=false;}}
function pause(){clearInterval(clock);clock=null;renderLive();}
function reset(){window.Workshop?.resetController();clearInterval(clock);clock=null;s=S.fresh();s.loop=layout!=='straight';s.externalPLC=!!$('useLadder')?.checked;s.autoFeed=$('sbAuto').checked;S.sync(config,s);if(s.loop)S.feed(config,s);render();}
function edited(){save();reset();}
function tokens(){return [['UPPER','Upper limit'],['LOWER','Lower limit'],['EXTENDED','Extended limit'],['RETRACTED','Retracted limit'],['RUN','Run input'],['READY','Ready'],['LOCAL','Local switch'],['NEXT_CLEAR','Next station clear'],['OCCUPIED','This station occupied'],['TRUE','Always true'],...config.map(c=>['S_'+c.id,c.id+' sensor'])];}
function options(value){return tokens().flatMap(([t,label])=>[[t,label+' = ON'],['!'+t,label+' = OFF']]).map(([t,label])=>`<option value="${t}" ${t===value?'selected':''}>${label}</option>`).join('');}
function render(){S.sync(config,s);if(!config.some(c=>c.id===selection))selection=config[0]?.id;const c=config.find(c=>c.id===selection);$('sbStations').innerHTML=config.map((c,i)=>`<button data-select="${c.id}" class="${c.id===selection?'selected':''}">${i+1}. ${S.titles[c.type]} <small>${c.id}</small></button>`).join('');$('sbAdd').disabled=config.length>=12;$('sbEditor').innerHTML=c?`<div class="panelhead"><h2>${c.id} · ${S.titles[c.type]}</h2><div class="sbeditbuttons"><button data-edit="left" class="quiet" ${config.indexOf(c)===0?'disabled':''}>Earlier</button><button data-edit="right" class="quiet" ${config.indexOf(c)===config.length-1?'disabled':''}>Later</button><button data-edit="remove" class="textbutton">Remove</button></div></div><div class="sbrule"><label>Contact 1<select id="sbA">${options(c.a)}</select></label><label>Connection<select id="sbJoin"><option ${c.join==='AND'?'selected':''}>AND</option><option ${c.join==='OR'?'selected':''}>OR</option></select></label><label>Contact 2<select id="sbB">${options(c.b)}</select></label><div class="sbcoil" id="sbCoil">( )<span>${c.id} ENABLE</span></div></div><div class="sbsettings"><label>${c.type==='lift'?'Upper hold time':c.type==='stop'?'Hold time':'Travel time'}<select id="sbSeconds">${[.3,.5,1,1.2,2,3,5,10].map(v=>`<option value="${v}" ${c.seconds===v?'selected':''}>${v} seconds</option>`).join('')}</select></label><button id="sbLocal" class="quiet">Local: OFF</button><button id="sbFault" class="quiet">Fault: OFF</button>${c.type==='reject'?'<button id="sbReject" class="quiet">Reject: OFF</button>':''}</div><p class="sbstationread" id="sbStationRead"></p>`:'<p class="helper">Your line is empty. Add a component to begin.</p>';window.Workshop?.stationPanel(c,c?s.stations[c.id]:null);renderLive();}
function renderLive(){window.Workshop?.live();$('sbLayoutNote').textContent=layout==='straight'?'Parts exit at the last station.':config.length<2?'Add at least two stations to run a loop.':'One box starts on the loop. Add more with Feed one box. One station stays empty to keep circulation moving.';const c=config.find(c=>c.id===selection),st=c?s.stations[c.id]:null;$('sbRun').textContent=clock?'Pause simulation':'Run line';$('sbCommand').textContent='Run input: '+(s.run?'ON':'OFF');$('sbCommand').setAttribute('aria-pressed',String(s.run));$('sbReady').textContent='Ready: '+(s.ready?'ON':'OFF');$('sbReady').setAttribute('aria-pressed',String(s.ready));$('sbStats').innerHTML=`<span>Fed <b>${s.fed}</b></span><span>${s.loop?'Laps (all boxes)':'Delivered'} <b>${s.loop?s.laps:s.delivered}</b></span><span>Rejected <b>${s.rejected}</b></span><span>On line <b>${Object.values(s.stations).filter(x=>x.box).length}</b></span><span>Time <b>${s.time.toFixed(1)}s</b></span>`;
 $('sbDiagram').classList.toggle('loopdiagram',layout!=='straight');
 if(layout!=='straight'){$('sbDiagram').setAttribute('viewBox','0 0 640 520');$('sbDiagram').style.width='100%';$('sbDiagram').innerHTML=LineLayout.draw(layout,config,s,selection);}else{
 const width=Math.max(680,config.length*180+40);$('sbDiagram').setAttribute('viewBox',`0 0 ${width} 240`);$('sbDiagram').style.width=width+'px';$('sbDiagram').innerHTML=config.length?config.map((c,i)=>{const st=s.stations[c.id],x=20+i*180,up=c.type==='lift'?(c.control==='separate'?st.position:st.phase==='raising'?Math.min(Math.max(0,st.elapsed-.3)/.8,1):st.phase==='at upper limit'?1:st.phase==='lowering'?Math.max(0,1-(st.elapsed-1.1-c.seconds)/.8):0):0,y=128-up*42,progress=c.type==='belt'||c.type==='sensor'?Math.min(st.elapsed/c.seconds,1):.5,bx=x+12+progress*90;return `<g><text x="${x}" y="22" fill="#f2e8d8" font-size="14">${c.id} · ${S.titles[c.type]}</text><path d="M${x+10} 166v24m130-24v24" stroke="#ad9488" stroke-width="5"/><rect x="${x}" y="${y}" width="156" height="28" rx="10" fill="${st.output?'#326f68':'#725462'}" stroke="${st.fault?'#ff766f':'#bfa998'}" stroke-width="2"/>${[20,50,80,110,140].map(dx=>`<circle cx="${x+dx}" cy="${y+14}" r="7" fill="#d8ccba"/>`).join('')}${c.type==='stop'?`<path d="M${x+133} ${st.position<=0?y+10:y-35}v35" stroke="#e8b754" stroke-width="7"/>`:''}${c.type==='lift'?`<path d="M${x+35} 180L${x+120} ${y+28}M${x+120} 180L${x+35} ${y+28}" stroke="#ad9488" stroke-width="3"/>`:''}${st.box?`<rect x="${bx}" y="${y-34}" width="34" height="33" rx="3" fill="#e8b754"/><text x="${bx+17}" y="${y-12}" text-anchor="middle" font-size="13" fill="#38232e">${st.box}</text>`:''}<circle cx="${x+145}" cy="52" r="6" fill="${st.box?'#e8b754':'#856e76'}"/><text x="${x}" y="55" fill="#dbc5bc" font-size="12">S_${c.id}: ${st.box?1:0} · Count ${st.count}</text><text x="${x}" y="214" fill="${st.fault?'#ff9280':'#f2e8d8'}" font-size="13">${st.phase}</text>${i<config.length-1?`<path d="M${x+160} 142h18" stroke="#e8b754" stroke-width="2"/>`:''}</g>`;}).join(''):'<text x="30" y="110" fill="#f2e8d8" font-size="20">Add a station to start your line.</text>';
 }
 const faults=config.filter(c=>s.stations[c.id].fault||s.stations[c.id].conflict).map(c=>c.id),waiting=config.filter(c=>s.stations[c.id].waiting>=5).map(c=>c.id);const status=!storage?'Design could not be saved in this browser.':faults.length?'Fault active: '+faults.join(', '):waiting.length?'Waiting over 5 seconds: '+waiting.join(', ')+'. Check the station conditions and downstream space.':'Design saved in this browser. Up to 12 stations.';if($('sbStatus').textContent!==status)$('sbStatus').textContent=status;
 if(st){$('sbLocal').textContent='Local: '+(st.local?'ON':'OFF');$('sbLocal').setAttribute('aria-pressed',String(st.local));$('sbFault').textContent='Fault: '+(st.fault?'ON':'OFF');$('sbFault').setAttribute('aria-pressed',String(st.fault));if($('sbReject')){$('sbReject').textContent='Reject: '+(st.reject?'ON':'OFF');$('sbReject').setAttribute('aria-pressed',String(st.reject));}$('sbCoil').classList.toggle('on',st.output);$('sbStationRead').textContent=`Sensor ${st.box?1:0} · Output ${st.output?1:0} · Arrivals ${st.count} · ${st.phase} · Elapsed ${st.elapsed.toFixed(1)}s${c.type==='lift'?' · Upper '+(st.phase==='at upper limit'?1:0)+' · Lower '+(['empty','arrived','at lower limit'].includes(st.phase)?1:0):''}`;}
}
function tick(dt=.1){S.step(config,s,dt);renderLive();}
$('sbLayout').onchange=()=>{layout=$('sbLayout').value;$('sbAuto').checked=layout==='straight';edited();};
$('sbDiagram').onclick=e=>{const station=e.target.closest('[data-station]');if(station){selection=station.dataset.station;render();}};
$('sbDiagram').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){const station=e.target.closest('[data-station]');if(station){e.preventDefault();selection=station.dataset.station;render();}}};
$('sbRun').onclick=()=>{if(clock)pause();else{s.run=true;clock=setInterval(()=>tick(.05),50);renderLive();}};$('sbStep').onclick=()=>{pause();tick();};$('sbCommand').onclick=()=>{s.run=!s.run;renderLive();};$('sbReady').onclick=()=>{s.ready=!s.ready;renderLive();};$('sbAuto').onchange=()=>{s.autoFeed=$('sbAuto').checked;};$('sbReset').onclick=reset;$('sbFeed').onclick=()=>{const ok=S.feed(config,s);renderLive();if(!ok)$('sbStatus').textContent=s.loop?'The entry is occupied, or the loop has reached its circulation limit. Keep one station empty.':'The entry station is occupied, or the line is empty.';};
$('sbAdd').onclick=()=>{if(config.length>=12)return;const id='N'+(Math.max(0,...config.map(c=>Number(c.id.slice(1))))+1);config.push({id,type:$('sbType').value,seconds:1,a:'RUN',b:'NEXT_CLEAR',join:'AND'});selection=id;edited();};$('sbStations').onclick=e=>{const b=e.target.closest('[data-select]');if(b){selection=b.dataset.select;render();}};
$('sbEditor').onchange=e=>{const c=config.find(c=>c.id===selection);if(!c)return;const map={sbA:'a',sbB:'b',sbJoin:'join',sbSeconds:'seconds'};const key=map[e.target.id];if(key){c[key]=key==='seconds'?Number(e.target.value):e.target.value;edited();}};
$('sbEditor').onclick=e=>{const b=e.target.closest('button');if(!b)return;const c=config.find(c=>c.id===selection);if(!c)return;const st=s.stations[c.id],k={sbLocal:'local',sbFault:'fault',sbReject:'reject'}[b.id];if(k){st[k]=!st[k];renderLive();return;}const i=config.indexOf(c),action=b.dataset.edit;if(action==='remove'){config.splice(i,1);for(const other of config)for(const key of ['a','b'])if(other[key].replace(/^!/,'')==='S_'+c.id)other[key]='!TRUE';}else if(action==='left'&&i>0)[config[i-1],config[i]]=[config[i],config[i-1]];else if(action==='right'&&i<config.length-1)[config[i+1],config[i]]=[config[i],config[i+1]];else return;edited();};
 document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.Sandbox={pause,render,getState:()=>({config,state:s,layout}),select:id=>{selection=id;render();},updateStation:(id,patch)=>{const c=config.find(x=>x.id===id);if(!c)return;Object.assign(c,patch);S.validate(config);edited();},loadDesign:(design)=>{config=S.validate(JSON.parse(JSON.stringify(design.config)));layout=['straight','square','oval'].includes(design.layout)?design.layout:'straight';$('sbLayout').value=layout;$('sbAuto').checked=layout==='straight';edited();},reset,enablePLC:on=>{s.externalPLC=on;reset();},step:()=>{pause();tick();return {time:s.time,delivered:s.delivered};}};render();
})();
